import test from 'node:test';
import assert from 'node:assert/strict';

import { parseRange } from '../src/parseRange.js';

test('expands an inclusive range', () => {
  assert.deepEqual(parseRange('3-7'), [3, 4, 5, 6, 7]);
});

test('throws on malformed input', () => {
  for (const input of ['', 'abc', '3-', '-7', '3..7', '3-7-9']) {
    assert.throws(() => parseRange(input), /bad range/, `expected ${JSON.stringify(input)} to be rejected`);
  }
});

test('throws on an inverted range', () => {
  assert.throws(() => parseRange('7-3'), /inverted range: 7-3/);
});

test('throws when the span is wider than 1000', () => {
  assert.throws(() => parseRange('1-1002'), /range too wide/);
  assert.deepEqual(parseRange('1-1001'), Array.from({ length: 1001 }, (_, i) => i + 1));
});

